// Show a Fighting Spirit's name as one caption and centre it.
local size = [0, 0];
if (CMND_2DO_CREATE_AVA_SUB_TELOP("spirit_name", 0, 12, 0, "ck0023", size, 6) != null)
{
	CMND_2DO_STATE_DRAW_TELOP("spirit_name", true);
	CMND_2DO_POS_SET_TELOP("spirit_name", 200 - size[0] / 2, 120);
}
